set -eu
task_root=/opt/market-mcp-deploy/mcp
test "$(realpath "$task_root")" = "$task_root"
python3 - <<'PY'
import ast,base64,hashlib,shutil,zlib
from datetime import datetime,timezone
from pathlib import Path
root=Path('/opt/market-mcp-deploy/mcp')
target=root/'market_data/reputation_server.py'
assert hashlib.sha256(target.read_bytes()).hexdigest()=='9d059465ebde7020356a14bb3d2dd4caecd25f78a05c27842ffba705ce6b9245','Source changed; stop'
assert not (root/'market_data/reputation_sources.py').exists(),'Unexpected existing extension; stop'
packed={
    "reputation_server.py": "",
    "reputation_sources.py": "",
}
backup=root/'deploy/backups'/('reputation-sources-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True,exist_ok=False)
shutil.copy2(target,backup/'reputation_server.py')
assert target.read_bytes()==(backup/'reputation_server.py').read_bytes()
for name,encoded in packed.items():
    payload=zlib.decompress(base64.b64decode(encoded))
    ast.parse(payload)
    path=root/'market_data'/name
    assert root in path.resolve().parents
    path.write_bytes(payload)
    print(name,hashlib.sha256(payload).hexdigest())
print('backup='+str(backup))
PY
cd "$task_root/deploy"
rollback_tag="market-reputation-rollback:$(date -u +%Y%m%dT%H%M%SZ)"
old_image=$(docker inspect --format '{{.Image}}' deploy-reputation-mcp-1)
docker image tag "$old_image" "$rollback_tag"
printf 'rollback_image=%s\n' "$rollback_tag"
docker compose build reputation-mcp
docker compose up -d --no-deps reputation-mcp
docker compose ps reputation-mcp
docker compose logs --tail=15 reputation-mcp
